function beginPhase(n){phase=n;let p=P[n];save.plays++;saveIt();tasks=p.tasks.map(id=>({...T[id],id,done:false}));time=p.time;pat=energy=100;noise=score=combo=comboT=0;maxCombo=1;particles.length=0;equipped=null;picked=new Set();usedHelp=new Set();tempTasks=[];optionalTasks=[];secretUsed=new Set();distraction=blackout=momPhone=slip=noiseCount=0;surpriseAdded=false;finaleDone=false;finalChase=false;finalChaseHiddenT=0;finalSearchTarget=null;if(Math.random()<.55)optionalTasks.push({id:"bonusbed",name:"BÔNUS: Arrumar a cama",x:500,y:360,d:3.5,icon:"🛏️",act:"Arrumando...",optional:true,done:false});doing=null;prog=0;red=false;lastPI=0;failStage="";pl={x:270,y:545,r:9,speed:175,dir:"up",walk:0,moving:false,hidden:false,isHidden:false,hideSpot:null,hideEntryPosition:null,hideExitPosition:null,hideWitnessed:false};interactPressed=false;interactCooldown=0;mom={x:55,y:180,r:10,target:{x:150,y:180},pause:0,walk:0,path:[],lastSeen:null,search:0,investigate:null,seenCool:0,aiState:"PATROL",hiddenTarget:null,currentSpeed:0};validateWorldObjects();state="playing";nextCall=7+Math.random()*8;callT=count=0;eventT=P[n].event*(.75+Math.random()*.5);event=null;rain=false;seen=alerts=stillT=runT=revisitT=0;$("#alert").style.display=$("#taskToast").style.display="none";$("#pause").classList.remove("active");hud();show("game")}
function cr(x,y,r,q){return x+r>q.x&&x-r<q.x+q.w&&y+r>q.y&&y-r<q.y+q.h}
function collisionRect(f){let ix=Math.min(9,f.w*.12),iy=Math.min(8,f.h*.12);if(f.k==="sofa"||f.k==="bed"){ix=Math.min(12,f.w*.1);iy=Math.min(10,f.h*.14)}return{x:f.x+ix,y:f.y+iy,w:Math.max(8,f.w-ix*2),h:Math.max(8,f.h-iy*2)}}
function blocked(x,y,r){return walls.some(q=>cr(x,y,r,q))||furn.some(f=>cr(x,y,r,collisionRect(f)))}
function move(e,dx,dy,dt){let ok=false,nx=e.x+dx*dt,ny=e.y+dy*dt;if(!blocked(nx,e.y,e.r)){e.x=nx;ok=true}if(!blocked(e.x,ny,e.r)){e.y=ny;ok=true}if(!ok&&Math.abs(dx)+Math.abs(dy)>0){const n=.75;if(!blocked(e.x+Math.sign(dx)*n,e.y,e.r)){e.x+=Math.sign(dx)*n;ok=true}if(!blocked(e.x,e.y+Math.sign(dy)*n,e.r)){e.y+=Math.sign(dy)*n;ok=true}}if(ok)e.walk=(e.walk||0)+dt*10;return ok}
function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}
function nearTask(includeDone=false){let b=null,d=INTERACT_RADIUS.task;for(const t of tasks)if(includeDone||!t.done){let q=dist(pl,t);if(q<d){b=t;d=q}}return b}
function nearHide(){let b=null,d=INTERACT_RADIUS.hide;for(const h of hides){let q=dist(pl,h);if(q<d){b=h;d=q}}return b}
function pointValid(x,y,clear=18){return x>28&&x<W-28&&y>28&&y<H-28&&!blocked(x,y,clear)}
function accessibleAround(o){if(!pointValid(o.x,o.y,10))return false;for(let a=0;a<Math.PI*2;a+=Math.PI/4)if(pointValid(o.x+Math.cos(a)*38,o.y+Math.sin(a)*38,9))return true;return false}
function findNearbyValid(o){for(let rad=24;rad<=110;rad+=18)for(let a=0;a<Math.PI*2;a+=Math.PI/8){let x=o.x+Math.cos(a)*rad,y=o.y+Math.sin(a)*rad;if(pointValid(x,y,12)){o.x=Math.round(x);o.y=Math.round(y);return true}}return false}
function findSafeDropPosition(){let p=playerFeet(),dir=pl.dir==="right"?[1,0]:pl.dir==="left"?[-1,0]:pl.dir==="down"?[0,1]:[0,-1],c=[];for(const r of [34,46,58,70]){c.push({x:p.x+dir[0]*r,y:p.y+dir[1]*r});for(let a=0;a<Math.PI*2;a+=Math.PI/4)c.push({x:p.x+Math.cos(a)*r,y:p.y+Math.sin(a)*r})}for(const q of c)if(pointValid(q.x,q.y,12))return{x:Math.round(q.x),y:Math.round(q.y)};return{x:p.x,y:p.y}}
function validateWorldObjects(){for(const o of [...tools,...helps,...interactives,...tasks])if(!accessibleAround(o))findNearbyValid(o);for(const n of nodes)if(!pointValid(n.x,n.y,10))findNearbyValid(n)}
function playerFeet(){return{x:pl.x,y:pl.y}}
function interactionDistance(o){let p=playerFeet();return Math.hypot(p.x-o.x,p.y-o.y)}
function facingBonus(o){let p=playerFeet(),dx=o.x-p.x,dy=o.y-p.y,d=Math.hypot(dx,dy)||1,v=pl.dir==="right"?[1,0]:pl.dir==="left"?[-1,0]:pl.dir==="down"?[0,1]:[0,-1];return Math.max(0,(dx/d)*v[0]+(dy/d)*v[1])}
function currentNeededIds(){let ids=new Set();for(const t of tasks)if(!t.done&&req[t.id]&&equipped!==req[t.id])ids.add(req[t.id]);return ids}
function interactionPriority(x){if(x.type==="tool"&&x.need)return 0;if(x.type==="tool")return 1;if(x.type==="task"||x.type==="object"&&x.need)return 2;if(x.type==="hide")return 3;return 4}
function getBestInteractionTarget(){if(!pl||pl.isHidden)return null;let needed=currentNeededIds(),c=[];const add=(o,type,rad,action)=>{if(!o)return;let d=interactionDistance(o);if(d>rad)return;let need=needed.has(o.id)||(type==="object"&&o.id==="sink"&&equipped==="bucket"&&tasks.some(t=>t.id==="bath"&&!t.done&&!t.filled));c.push({o,type,action,d,rad,need,face:facingBonus(o)})};
for(const o of tools)if(!picked.has(o.id))add(o,"tool",INTERACT_RADIUS.tool,"pickup");
for(const o of helps)if(!usedHelp.has(o.id)&&energyItemsForPhase().includes(o.id))add(o,"help",INTERACT_RADIUS.help,"help");
for(const o of interactives)if(!secretUsed.has(o.id)||o.kind==="water")add(o,"object",INTERACT_RADIUS.object,"object");
for(const o of [...tempTasks,...optionalTasks,...tasks])if(!o.done)add(o,"task",INTERACT_RADIUS.task,"task");
for(const o of hides)add(o,"hide",INTERACT_RADIUS.hide,"hide");
c.sort((a,b)=>interactionPriority(a)-interactionPriority(b)||a.d-b.d||b.face-a.face);return c[0]||null}
function consumeInteraction(){interactPressed=false;interactCooldown=.14}
function debugInteraction(hit){if(!DEBUG_INTERACTIONS||!pl)return;let p=playerFeet();console.debug("[INTERACTION]",{player:p,interaction:p,target:hit?.o?.id||null,targetPosition:hit?.o?{x:hit.o.x,y:hit.o.y}:null,distance:hit?.d??null,radius:hit?.rad??null,state,equipped,isHidden:pl.isHidden,isBusy:!!doing})}
function energyItemsForPhase(){return phase===0?["juice","cookie","banana"]:phase===1?["juice","cookie","banana"]:["juice","snack"]}
function highlight(o,t=2.5){highlightTarget=o;highlightT=t}
function findSafeHideExitPosition(h,preferred=null){let candidates=[];if(preferred)candidates.push(preferred);if(h?.exitX!=null)candidates.push({x:h.exitX,y:h.exitY});if(pl?.hideEntryPosition)candidates.push(pl.hideEntryPosition);let cx=h?.x??pl.x,cy=h?.y??pl.y;for(let rad=28;rad<=110;rad+=16)for(let a=0;a<Math.PI*2;a+=Math.PI/8)candidates.push({x:cx+Math.cos(a)*rad,y:cy+Math.sin(a)*rad});for(const p of candidates)if(pointValid(p.x,p.y,pl?.r||9))return{x:Math.round(p.x),y:Math.round(p.y)};return{x:270,y:545}}
function enterHide(h){if(!h||!pl||pl.isHidden)return;let witnessed=visible()&&dist(pl,mom)<150&&(mom.aiState==="CHASE"||pidx()>=2);pl.hideEntryPosition={x:pl.x,y:pl.y};pl.hideSpot=h;pl.hideExitPosition=findSafeHideExitPosition(h,{x:h.exitX,y:h.exitY});pl.hideWitnessed=witnessed;pl.isHidden=pl.hidden=true;pl.moving=false;doing=null;prog=0;if(!witnessed){mom.aiState="SEARCHING";mom.search=searchDuration();mom.lastSeen={x:pl.x,y:pl.y}}else{mom.hiddenTarget=h;mom.aiState="CHASE"}$("#progressBox").style.display="none";eventMsg(witnessed?"👀 ELA VIU VOCÊ ENTRAR!":"👀 ESCONDIDO • [E] SAIR")}
function exitHide(reason="manual"){if(!pl)return;let h=pl.hideSpot,pos=findSafeHideExitPosition(h,pl.hideExitPosition);pl.hidden=pl.isHidden=false;pl.hideSpot=null;pl.hideEntryPosition=null;pl.hideExitPosition=null;pl.hideWitnessed=false;pl.moving=false;doing=null;prog=0;if(pos){pl.x=pos.x;pl.y=pos.y}if(reason==="manual")eventMsg("👟 Saiu do esconderijo.")}
