function lineClear(a,b){let steps=Math.ceil(dist(a,b)/12);for(let i=1;i<steps;i++){let x=a.x+(b.x-a.x)*i/steps,y=a.y+(b.y-a.y)*i/steps;if(blocked(x,y,6))return false}return true}
function visible(){return !pl.isHidden&&dist(pl,mom)<(pidx()>=2?250:190)&&lineClear(pl,mom)}
function nearestNode(pos){let best=nodes[0],d=1e9;for(const n of nodes){let q=dist(pos,n);if(q<d){d=q;best=n}}return best}
function pathTo(target){let a=nearestNode(mom),b=nearestNode(target);if(a===b)return [target];let ai=nodes.indexOf(a),bi=nodes.indexOf(b),path=[];const adj=(i,j)=>dist(nodes[i],nodes[j])<210&&lineClear(nodes[i],nodes[j]);let q=[ai],prev=Array(nodes.length).fill(-1),seenN=new Set([ai]);while(q.length){let i=q.shift();if(i===bi)break;for(let j=0;j<nodes.length;j++)if(!seenN.has(j)&&adj(i,j)){seenN.add(j);prev[j]=i;q.push(j)}}if(prev[bi]!==-1||ai===bi){let cur=bi;while(cur!==ai){path.unshift(nodes[cur]);cur=prev[cur]}path.unshift(a)}path.push(target);return path}
function follow(target,speed,dt){if(!target)return;let steps=Math.max(1,Math.ceil(speed*dt/7)),sd=dt/steps;for(let k=0;k<steps;k++){if(!mom.path.length||dist(mom.path[mom.path.length-1],target)>45)mom.path=pathTo(target);let t=mom.path[0]||target;if(dist(mom,t)<15){mom.path.shift();t=mom.path[0]||target}let dx=t.x-mom.x,dy=t.y-mom.y,d=Math.hypot(dx,dy)||1;move(mom,dx/d*speed,dy/d*speed,sd)}}
function patrolTarget(){let candidates=pidx()===1?[...tasks.filter(t=>!t.done),...(pl.history||[])]:nodes;let t=candidates[Math.floor(Math.random()*candidates.length)]||nodes[0];return{x:t.x,y:t.y}}
function phaseProgress(){return Math.max(0,Math.min(1,1-time/P[phase].time))}
function searchDuration(){return[4.5,6.5,8.5][phase]}
